import{_ as s,o as n,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"API 契约与前后端联调","description":"用一份双方都认可、可校验的 API 契约驱动前后端并行开发，用 mock 和变更通知替代口头沟通。","frontmatter":{"title":"API 契约与前后端联调","description":"用一份双方都认可、可校验的 API 契约驱动前后端并行开发，用 mock 和变更通知替代口头沟通。"},"headers":[],"relativePath":"engineering/api-contract.md","filePath":"engineering/api-contract.md","lastUpdated":1786271684000}'),e={name:"engineering/api-contract.md"};function p(l,a,d,h,o,r){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="api-契约与前后端联调" tabindex="-1">API 契约与前后端联调 <a class="header-anchor" href="#api-契约与前后端联调" aria-label="Permalink to &quot;API 契约与前后端联调&quot;">​</a></h1><p>前后端联调的痛苦，几乎都来自同一件事：没有契约。后端凭感觉改了个字段名，前端不知道；前端按口头描述写的逻辑，后端实际返回的结构对不上；联调那天才发现两边理解完全不同，互相等、互相改、互相怨。API 契约要解决的就是这个——让接口的形状成为一份双方都认可、可校验、可版本化的协议，而不是聊天记录里的一句话。</p><h2 id="为什么需要契约" tabindex="-1">为什么需要契约 <a class="header-anchor" href="#为什么需要契约" aria-label="Permalink to &quot;为什么需要契约&quot;">​</a></h2><p>没有契约时，接口的定义散落在聊天记录、文档、代码三处，而且彼此不一致：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>口头约定：&quot;返回用户列表，每条有 id 和 name&quot;</span></span>
<span class="line"><span>后端实际：返回 { userId, userName, ... }</span></span>
<span class="line"><span>前端预期：[{ id, name }]</span></span>
<span class="line"><span>联调当天：互相阻塞，谁也动不了</span></span></code></pre></div><p>契约的价值在于<strong>单一事实来源</strong>：接口长什么样、字段叫什么、什么类型、什么必填，都由一份明确的描述决定，前后端都以此为准。</p><table tabindex="0"><thead><tr><th>没有契约</th><th>有契约</th></tr></thead><tbody><tr><td>接口定义在聊天记录里</td><td>一份机器可读的描述文件</td></tr><tr><td>改了字段没人知道</td><td>改动触发通知和影响分析</td></tr><tr><td>联调当天才发现对不上</td><td>各自按契约开发，提前对齐</td></tr><tr><td>出问题互相甩锅</td><td>以契约为准，对错明确</td></tr></tbody></table><h2 id="openapi-与类型共享" tabindex="-1">OpenAPI 与类型共享 <a class="header-anchor" href="#openapi-与类型共享" aria-label="Permalink to &quot;OpenAPI 与类型共享&quot;">​</a></h2><p>OpenAPI（前身 Swagger）是事实标准的 REST API 描述格式。一份 OpenAPI 文件既描述了接口，又能直接派生出多种产物：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenAPI 定义（openapi.yaml）</span></span>
<span class="line"><span>  → 后端：生成路由骨架、请求校验、mock</span></span>
<span class="line"><span>  → 前端：生成 TypeScript 类型和请求客户端</span></span>
<span class="line"><span>  → 文档：自动渲染的 API 文档</span></span>
<span class="line"><span>  → 测试：契约一致性校验</span></span></code></pre></div><p>最大的收益是<strong>类型从契约自动生成</strong>，而不是前端手写一遍、后端手写一遍。手写的两份类型迟早会不一致，自动生成保证它们同源。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 从 OpenAPI 生成的类型，永远和后端一致</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Order</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  amount</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pending&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;paid&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;shipped&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="mock-与并行开发" tabindex="-1">Mock 与并行开发 <a class="header-anchor" href="#mock-与并行开发" aria-label="Permalink to &quot;Mock 与并行开发&quot;">​</a></h2><p>契约确定后，前后端不用再互相等。后端还没实现，前端可以基于契约 mock 数据先开发：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 双方一起定契约（OpenAPI）</span></span>
<span class="line"><span>2. 前端用 mock server 按契约返回假数据，开发 UI</span></span>
<span class="line"><span>3. 后端按契约实现接口</span></span>
<span class="line"><span>4. 联调时前端把 mock 切换成真实接口</span></span></code></pre></div><p>mock 要基于契约而不是前端自己瞎编——否则 mock 和真实接口又是两套。常用的做法是用专门的 mock 工具直接读 OpenAPI 文件，返回符合 schema 的假数据。</p><h2 id="变更通知-契约是会改的" tabindex="-1">变更通知：契约是会改的 <a class="header-anchor" href="#变更通知-契约是会改的" aria-label="Permalink to &quot;变更通知：契约是会改的&quot;">​</a></h2><p>契约不是一次定死，它会演进。关键是要让<strong>契约的变更可见、可协商</strong>，而不是悄悄改：</p><table tabindex="0"><thead><tr><th>变更类型</th><th>影响</th><th>处理</th></tr></thead><tbody><tr><td>新增可选字段</td><td>非破坏性</td><td>直接加，通知即可</td></tr><tr><td>新增接口</td><td>非破坏性</td><td>加，通知</td></tr><tr><td>改字段名/类型</td><td>破坏性</td><td>必须协商，前端同意</td></tr><tr><td>删除字段</td><td>破坏性</td><td>必须走版本协商或废弃周期</td></tr></tbody></table><p>破坏性变更最危险。一个看似无害的改动（<code>userId</code> 改成 <code>id</code>），能让前端整个页面崩掉。规则：<strong>任何破坏性变更必须走评审，并在 CI 里用契约校验工具拦截</strong>，而不是靠人记得。</p><h2 id="版本协商" tabindex="-1">版本协商 <a class="header-anchor" href="#版本协商" aria-label="Permalink to &quot;版本协商&quot;">​</a></h2><p>当改动确实是破坏性的，靠版本协商来过渡：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>策略一：URL 版本</span></span>
<span class="line"><span>  /api/v1/orders  →  /api/v2/orders</span></span>
<span class="line"><span>  v1 保持可用，新功能进 v2，逐步迁移</span></span>
<span class="line"><span></span></span>
<span class="line"><span>策略二：header 版本 / 内容协商</span></span>
<span class="line"><span>  Accept: application/vnd.myapp.v2+json</span></span></code></pre></div><p>不管哪种策略，核心是<strong>旧版本要有明确的废弃周期</strong>，给消费者时间迁移，而不是改完就删。同时监控旧版本的调用量，等它趋零再下线。</p><h2 id="文档即契约" tabindex="-1">文档即契约 <a class="header-anchor" href="#文档即契约" aria-label="Permalink to &quot;文档即契约&quot;">​</a></h2><p>最好的 API 文档就是契约本身——OpenAPI 文件自动渲染出的文档，永远和实现一致。手写的 wiki 文档最大的问题是它会过期，没人维护，最后没人信。</p><blockquote><p>一个简单的判断标准：如果文档和代码不一致，应该是代码错了（没按契约实现），而不是文档过期了。让契约成为唯一事实，两边都向它对齐。</p></blockquote><p>实现层面，可以在 CI 里加一步<strong>契约校验</strong>：拿真实接口的响应去匹配 OpenAPI schema，不匹配就失败。这样后端偷偷改了返回结构，CI 会直接报红。</p><h2 id="前后端协作流程" tabindex="-1">前后端协作流程 <a class="header-anchor" href="#前后端协作流程" aria-label="Permalink to &quot;前后端协作流程&quot;">​</a></h2><p>把契约驱动串成一条流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 需求评审后，前后端一起定 API 契约（OpenAPI）</span></span>
<span class="line"><span>2. 契约进版本控制，评审后合并</span></span>
<span class="line"><span>3. 前端基于契约 mock 开发，后端基于契约实现</span></span>
<span class="line"><span>4. CI 校验实现与契约一致</span></span>
<span class="line"><span>5. 联调时切换 mock → 真实接口</span></span>
<span class="line"><span>6. 后续变更走契约评审 + 变更通知</span></span></code></pre></div><p>这套流程把&quot;联调当天的互相等待&quot;前置成了&quot;早期的契约对齐&quot;。联调成本越早付出越便宜，越晚越贵。</p><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>是否有一份机器可读的 API 契约作为单一事实来源？</li><li>前后端的类型是否从契约自动生成，而不是各自手写？</li><li>前端是否能基于契约 mock 并行开发，不用等后端？</li><li>破坏性变更是否走评审和通知，而不是悄悄改？</li><li>CI 是否校验实现与契约一致，防止文档和代码漂移？</li><li>旧版本接口是否有废弃周期和调用量监控，而不是改完就删？</li></ul>`,34)])])}const g=s(e,[["render",p]]);export{k as __pageData,g as default};
